import { useCallback, useState } from 'react';
import { AttendeeServices } from '@/api';
import { useAttendeesStore } from '@/store';
import { CallStatus } from '@/types/api.types';
import { logger } from '@/utils/logger';

/**
 * Manual re-fetch of the attendee list. Unlike ApiGlobalStateManager this never clears the
 * store first, so the page keeps rendering the current data (instead of blanking out) while
 * the request is in flight, and a failed refresh leaves the previous list on screen.
 */
export const useAttendeeListRefresh = (eventId: string) => {
    const { setAttendeeListState } = useAttendeesStore();
    const [refreshing, setRefreshing] = useState(false);

    const refresh = useCallback(async () => {
        if (!eventId) return;
        setRefreshing(true);
        try {
            const response = await AttendeeServices.GetAttendees(eventId);
            setAttendeeListState({
                status: CallStatus.Success,
                data: response.data.result || [],
                httpStatus: response.data.status,
                timestamp: new Date(),
            });
        } catch (error) {
            logger.error('useAttendeeListRefresh', 'Failed to refresh attendees', error);
        } finally {
            setRefreshing(false);
        }
    }, [eventId, setAttendeeListState]);

    return { refresh, refreshing };
};
